import sys

def main():
    A, B, C = map(int, sys.stdin.read().split())
    lo, hi = 1, max(B, C)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if B // mid + C // mid >= A:
            lo = mid
        else:
            hi = mid - 1
    print(lo)

